const base=$('🧩 Résultat Contenu').first().json;
const plan=parseStrictAI($input.first().json,'Directeur Marketing IA');
const allowed=new Set((base.products||[]).map(p=>p.productId));
if(plan.priorityProduct?.productId && !allowed.has(plan.priorityProduct.productId)){
  throw new Error('Directeur Marketing IA: priorityProduct ne correspond pas au catalogue Shopify analysé');
}
plan.seoUpdates=(Array.isArray(plan.seoUpdates)?plan.seoUpdates:[])
  .filter(x=>x&&allowed.has(x.productId)&&x.seoTitle&&x.seoDescription)
  .slice(0,3)
  .map(x=>({...x,confidence:Math.max(0,Math.min(100,Number(x.confidence||0)))}));
plan.contentPlan=Array.isArray(plan.contentPlan)?plan.contentPlan:[];
plan.retentionPlan=Array.isArray(plan.retentionPlan)?plan.retentionPlan:[];
plan.kpis=Array.isArray(plan.kpis)?plan.kpis:[];
plan.next7Days=Array.isArray(plan.next7Days)?plan.next7Days.slice(0,7):[];
if(typeof plan.requiresHumanApproval!=='boolean') plan.requiresHumanApproval=true;
return [{json:{...base,finalPlan:plan}}];

